return [
  {
    json: {
      enquiryId: 'sample-complete-001',
      name: 'Amina Rahman',
      email: 'AMINA@EXAMPLE.COM ',
      task: 'Prepare a summary of website enquiries for review before follow-up',
      currentSystem: 'Website form and spreadsheet',
      frequency: 'Daily',
      owner: 'Sales coordinator',
      customerFacingAction: true
    }
  },
  {
    json: {
      enquiryId: 'sample-needs-details-002',
      name: 'Jon Bell',
      email: 'jon.example.com',
      task: '',
      currentSystem: 'Not yet specified',
      frequency: 'Weekly',
      owner: '',
      customerFacingAction: false
    }
  }
];

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function fingerprint(value) {
  let hash = 2166136261;
  for (let i = 0; i < value.length; i += 1) {
    hash ^= value.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return `sample-${(hash >>> 0).toString(16).padStart(8, '0')}`;
}

return $input.all().map((item) => {
  const source = item.json;
  const normalizedEmail = String(source.email || '').trim().toLowerCase();
  const task = String(source.task || '').trim();
  const owner = String(source.owner || '').trim();
  const missingFields = [];

  if (!String(source.name || '').trim()) missingFields.push('name');
  if (!emailPattern.test(normalizedEmail)) missingFields.push('valid email');
  if (!task) missingFields.push('task');
  if (!owner) missingFields.push('owner');

  const requiresHumanReview = missingFields.length > 0;
  const reviewReason = requiresHumanReview
    ? `Clarify: ${missingFields.join(', ')}`
    : source.customerFacingAction
      ? 'Inputs are complete; keep human approval before any customer-facing follow-up.'
      : 'Inputs are complete; review the pilot output before enabling downstream actions.';

  return {
    json: {
      enquiryId: source.enquiryId,
      name: String(source.name || '').trim(),
      normalizedEmail,
      task,
      currentSystem: String(source.currentSystem || '').trim(),
      frequency: String(source.frequency || '').trim(),
      owner,
      customerFacingAction: Boolean(source.customerFacingAction),
      missingFields,
      requiresHumanReview,
      reviewReason,
      fingerprint: fingerprint(`${normalizedEmail}|${task.toLowerCase()}`)
    }
  };
});
